# এসএসসি সাধারণ গণিত অধ্যায় ৪ (সূচক ও লগারিদম): সৃজনশীল প্রশ্ন — অনুশীলনী ৪.১ ও ৪.২, প্রতিটিতে ৫টি; ক (২), খ (৪), গ (৪)
import json, os, math, sympy as sp
from sympy import Rational as R, cbrt, sqrt, log
x,y,a,b,c,n=sp.symbols('x y a b c n',positive=True)
Q=lambda u,v: abs(sp.N(u-v,30))<1e-20
E=lambda p,q: sp.simplify(p-q)==0

# ---------- যাচাই ৪.১ ----------
t=cbrt(3)+1/cbrt(3); assert Q(cbrt(3)**3+(1/cbrt(3))**3,R(10,3)) and Q(3*t**3-9*t,10)
s=cbrt(2)-1/cbrt(2); assert Q(2*s**3+6*s,3)
A_=2**(x+3)+2**(x+1); B_=2**(x+2)-2**x; assert E(A_,10*2**x) and E(B_,3*2**x) and E(A_/B_,R(10,3)) and sp.solve(10*2**x-160,x)==[4] and 3*16==48
f=lambda v:4**v; assert f(R(3,2))==8 and sp.solve(f(x+1)+f(x)-80,x)==[2] and set(sp.solve(f(x)-6*2**x+8,x))=={1,2}
X,Y=3,R(1,2); B2=2**X; C2=sp.sqrt(B2); assert B2==8 and C2==2*sqrt(2) and Q(C2**R(2,3),2) and X*Y*R(2,3)==1
assert E(3**(x+2)+3**(x+1),12*3**x) and sp.solve(12*3**x-108,x)==[2] and sp.solve(2**(y+2)-4**(y-1),y)==[4]
# ---------- যাচাই ৪.২ ----------
l2,l3=0.3010,0.4771; assert round(l2+l3,4)==0.7781 and round(3*l2+2*l3,4)==1.8572 and round(l3-l2,4)==0.1761 and round(l3/l2,3)==1.585 and round(1+l3/l2,3)==2.585 and abs(math.log10(72)-1.8572)<2e-4
assert sp.solve(x**2-9-16,x)==[5] and log(125,5)==3 and sp.simplify(log(25)/log(sqrt(5)))==4
A2=sp.log(3,2); B3=sp.log(4,3); assert E(A2*B3,2) and E(sp.log(36,2),2+2*A2) and E(sp.log(24,6),(3+A2)/(1+A2))
X_=sp.log(b*c)/sp.log(a); Y_=sp.log(c*a)/sp.log(b); Z_=sp.log(a*b)/sp.log(c); assert E(1/(X_+1)+1/(Y_+1)+1/(Z_+1),1)
assert (sp.log(32,2),sp.log(16,4),sp.log(8,8))==(5,2,1) and R(1,6)+R(1,3)+R(1,2)==1
assert sp.expand((a+b)**2-(a**2+b**2+2*a*b))==0 and sp.expand((x+2*y)**2-(x**2+4*y**2+4*x*y))==0
p_=(7+3*sqrt(5))/2; assert Q(p_**2+1-7*p_,0) and Q(log((p_+1)/3)-(log(p_)+log(1))/2,0)  # a=p_, b=1 এ যাচাই
xx,yy=sp.symbols('xx yy',positive=True); r_=sp.solve(xx**2+4-12*xx,xx); assert all(Q(log((v+2)/4)-(log(v)+log(1))/2,0) for v in r_)

E41=[
("a = ∛3 + 1/∛3",
 ["(∛3)³ + (1/∛3)³ এর মান নির্ণয় কর।","দেখাও যে, 3a³ − 9a = 10","b = ∛2 − 1/∛2 হলে দেখাও যে, 2b³ + 6b = 3"],
 "ক) (∛3)³ + (1/∛3)³ = 3 + 1/3 = 10/3\nখ) a³ = (∛3)³ + (1/∛3)³ + 3 · ∛3 · (1/∛3)(∛3 + 1/∛3)\n⇒ a³ = 10/3 + 3a ⇒ 3a³ = 10 + 9a ⇒ 3a³ − 9a = 10\nগ) b³ = (∛2)³ − (1/∛2)³ − 3 · ∛2 · (1/∛2)(∛2 − 1/∛2)\n⇒ b³ = 2 − 1/2 − 3b = 3/2 − 3b ⇒ 2b³ = 3 − 6b ⇒ 2b³ + 6b = 3",'কঠিন'),
("A = 2ˣ⁺³ + 2ˣ⁺¹ এবং B = 2ˣ⁺² − 2ˣ",
 ["A ও B কে 2ˣ এর মাধ্যমে প্রকাশ কর।","দেখাও যে, A/B এর মান x এর উপর নির্ভর করে না।","A = 160 হলে x এর মান নির্ণয় কর এবং তখন B এর মান নির্ণয় কর।"],
 "ক) A = 2ˣ · 2³ + 2ˣ · 2 = 2ˣ(8 + 2) = 10 · 2ˣ\nB = 2ˣ · 2² − 2ˣ = 2ˣ(4 − 1) = 3 · 2ˣ\nখ) A/B = (10 · 2ˣ)/(3 · 2ˣ) = 10/3, যা একটি ধ্রুবক\n∴ A/B এর মান x এর উপর নির্ভর করে না।\nগ) 10 · 2ˣ = 160 ⇒ 2ˣ = 16 = 2⁴ ⇒ x = 4\nB = 3 · 2⁴ = 48",'মধ্যম'),
("f(x) = 4ˣ একটি ফাংশন।",
 ["f(3/2) এর মান নির্ণয় কর।","সমাধান কর: f(x + 1) + f(x) = 80","সমাধান কর: f(x) − 6 · 2ˣ + 8 = 0"],
 "ক) f(3/2) = 4^(3/2) = (2²)^(3/2) = 2³ = 8\nখ) 4ˣ⁺¹ + 4ˣ = 80 ⇒ 4ˣ(4 + 1) = 80 ⇒ 4ˣ = 16 = 4² ⇒ x = 2\nগ) 4ˣ = (2ˣ)²; 2ˣ = y ধরে y² − 6y + 8 = 0 ⇒ (y − 2)(y − 4) = 0\ny = 2 ⇒ 2ˣ = 2 ⇒ x = 1; y = 4 ⇒ 2ˣ = 2² ⇒ x = 2\n∴ x = 1, 2",'কঠিন'),
("aˣ = b, bʸ = c এবং cᶻ = a, যেখানে a, b, c ধনাত্মক ও 1 নয়।",
 ["b ও c কে a এর ঘাত আকারে প্রকাশ কর।","দেখাও যে, xyz = 1","a = 2, x = 3 এবং y = 1/2 হলে b, c ও z এর মান নির্ণয় করে খ এর ফল যাচাই কর।"],
 "ক) b = aˣ; c = bʸ = (aˣ)ʸ = aˣʸ\nখ) a = cᶻ = (aˣʸ)ᶻ = aˣʸᶻ\nএকই ভিত্তি a (a ≠ 1) ⇒ xyz = 1\nগ) b = 2³ = 8; c = 8^(1/2) = √8 = 2√2 = 2^(3/2)\ncᶻ = a ⇒ 2^(3z/2) = 2¹ ⇒ 3z/2 = 1 ⇒ z = 2/3\nxyz = 3 × (1/2) × (2/3) = 1 ✓",'কঠিন'),
("3ˣ⁺² + 3ˣ⁺¹ = 108",
 ["বাম পক্ষকে 3ˣ এর মাধ্যমে প্রকাশ কর।","x এর মান নির্ণয় কর।","প্রাপ্ত x এর মান ব্যবহার করে 2ʸ⁺ˣ = 4ʸ⁻¹ সমীকরণটি সমাধান কর।"],
 "ক) 3ˣ⁺² + 3ˣ⁺¹ = 3ˣ · 9 + 3ˣ · 3 = 12 · 3ˣ\nখ) 12 · 3ˣ = 108 ⇒ 3ˣ = 9 = 3² ⇒ x = 2\nগ) x = 2 ⇒ 2ʸ⁺² = 4ʸ⁻¹ = 2²ʸ⁻²\n⇒ y + 2 = 2y − 2 ⇒ y = 4",'মধ্যম'),
]
E42=[
("log 2 = 0.3010 এবং log 3 = 0.4771 (ভিত্তি 10)।",
 ["log 6 এর মান নির্ণয় কর।","log 72 ও log 1.5 এর মান নির্ণয় কর।","2ˣ = 3 হলে x এর আসন্ন মান (তিন দশমিক স্থান পর্যন্ত) এবং log₂ 6 এর মান নির্ণয় কর।"],
 "ক) log 6 = log (2 × 3) = log 2 + log 3 = 0.3010 + 0.4771 = 0.7781\nখ) log 72 = log (2³ × 3²) = 3 log 2 + 2 log 3 = 0.9030 + 0.9542 = 1.8572\nlog 1.5 = log (3/2) = log 3 − log 2 = 0.1761\nগ) 2ˣ = 3 ⇒ x log 2 = log 3 ⇒ x = 0.4771/0.3010 ≈ 1.585\nlog₂ 6 = log₂ 2 + log₂ 3 = 1 + x ≈ 2.585",'মধ্যম'),
("log₂(x + 3) + log₂(x − 3) = 4",
 ["লগারিদমের সূত্র প্রয়োগ করে সমীকরণটিকে একটি লগের আকারে লেখ।","সমীকরণটি সমাধান কর।","প্রাপ্ত x এর জন্য log_(x)(x³) + log_(√x) 25 এর মান নির্ণয় কর।"],
 "ক) log₂{(x + 3)(x − 3)} = 4 ⇒ log₂(x² − 9) = 4\nখ) x² − 9 = 2⁴ = 16 ⇒ x² = 25 ⇒ x = ±5\nx = −5 হলে log₂(x − 3) অসংজ্ঞায়িত ⇒ x = 5\nগ) log₅ 5³ = 3\nlog_(√5) 25 = log_(√5) (√5)⁴ = 4\nমান = 3 + 4 = 7",'মধ্যম'),
("a = log₂ 3 এবং b = log₃ 4",
 ["ab এর মান নির্ণয় কর।","log₂ 36 কে a এর মাধ্যমে প্রকাশ কর।","দেখাও যে, log₆ 24 = (3 + a)/(1 + a)"],
 "ক) ab = log₂ 3 × log₃ 4 = log₂ 4 = 2\nখ) log₂ 36 = log₂ (2² × 3²) = 2 + 2 log₂ 3 = 2 + 2a\nগ) ভিত্তি পরিবর্তন সূত্রে log₆ 24 = (log₂ 24) ÷ (log₂ 6)\nlog₂ 24 = log₂ (2³ × 3) = 3 + a, log₂ 6 = log₂ (2 × 3) = 1 + a\n∴ log₆ 24 = (3 + a)/(1 + a)",'কঠিন'),
("x = log_(a)(bc), y = log_(b)(ca) এবং z = log_(c)(ab), যেখানে a, b, c ধনাত্মক ও 1 নয়।",
 ["দেখাও যে, x + 1 = log_(a)(abc)","দেখাও যে, 1/(x + 1) + 1/(y + 1) + 1/(z + 1) = 1","a = 2, b = 4, c = 8 হলে x, y, z এর মান নির্ণয় করে খ এর ফল যাচাই কর।"],
 "ক) x + 1 = log_(a)(bc) + log_(a) a = log_(a)(abc)\nখ) একইভাবে y + 1 = log_(b)(abc), z + 1 = log_(c)(abc)\nlog_(a) M × log_(M) a = 1 সূত্রে, 1/(x + 1) = log_(abc) a\nএকইভাবে 1/(y + 1) = log_(abc) b, 1/(z + 1) = log_(abc) c\nযোগফল = log_(abc) a + log_(abc) b + log_(abc) c = log_(abc)(abc) = 1\nগ) x = log₂ 32 = 5, y = log₄ 16 = 2, z = log₈ 8 = 1\n1/6 + 1/3 + 1/2 = (1 + 2 + 3)/6 = 1 ✓",'কঠিন'),
("a² + b² = 7ab, যেখানে a, b ধনাত্মক।",
 ["দেখাও যে, (a + b)² = 9ab","প্রমাণ কর যে, log {(a + b)/3} = (1/2)(log a + log b)","x² + 4y² = 12xy (x, y ধনাত্মক) হলে প্রমাণ কর যে, log {(x + 2y)/4} = (1/2)(log x + log y)"],
 "ক) (a + b)² = a² + b² + 2ab = 7ab + 2ab = 9ab\nখ) (a + b)² = 9ab ⇒ {(a + b)/3}² = ab\nউভয় পক্ষে লগ নিয়ে 2 log {(a + b)/3} = log a + log b\n⇒ log {(a + b)/3} = (1/2)(log a + log b)\nগ) (x + 2y)² = x² + 4y² + 4xy = 12xy + 4xy = 16xy\n⇒ {(x + 2y)/4}² = xy ⇒ 2 log {(x + 2y)/4} = log x + log y\n⇒ log {(x + 2y)/4} = (1/2)(log x + log y)",'কঠিন'),
]
items=[]
for k_,(ex,L) in enumerate((('4.1',E41),('4.2',E42))):
    assert len(L)==5
    for i,(s_,p_,a_,lv) in enumerate(L):
        assert len(p_)==3 and a_.count('ক)')==1 and a_.count('খ)')==1 and a_.count('গ)')==1
        items.append({'n':f'b{k_*5+i+1}','ex':ex,'stem':s_,'p':p_,'a':a_,'lv':lv})
